#include <array>
#include <iostream>
#include <queue>
#include <set>
#include <vector>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    array<int, 3> colors{};
    for (int i = 0; i < n; ++i) {
        char c;
        cin >> c;
        if (c == 'R')
            ++colors[0];
        else if (c == 'G')
            ++colors[1];
        else if (c == 'B')
            ++colors[2];
        else
            --i;
    }

    const size_t base = static_cast<size_t>(n) + 1;
    vector<unsigned char> visited(base * base * base, false);
    queue<array<int, 3>> q;
    set<char> result;

    auto push = [&](int a, int b, int c) {
        size_t id = (static_cast<size_t>(a) * base + b) * base + c;
        if (!visited[id]) {
            visited[id] = true;
            q.push({a, b, c});
        }
    };

    push(colors[0], colors[1], colors[2]);

    while (!q.empty() && result.size() < 3) {
        auto [a, b, c] = q.front();
        q.pop();

        if (a == 0 && b == 0) {
            result.insert('B');
        } else if (b == 0 && c == 0) {
            result.insert('R');
        } else if (a == 0 && c == 0) {
            result.insert('G');
        } else {
            if (a > 0 && b > 0)
                push(a - 1, b - 1, c + 1);
            if (b > 0 && c > 0)
                push(a + 1, b - 1, c - 1);
            if (a > 0 && c > 0)
                push(a - 1, b + 1, c - 1);

            if (a > 1 && a < 3)
                push(a - 1, b, c);
            if (b > 1 && b < 3)
                push(a, b - 1, c);
            if (c > 1 && c < 3)
                push(a, b, c - 1);
        }
    }

    for (char c : result)
        cout << c;

    return 0;
}

