using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    array<int, 3> count{};
    for (int i = 0; i < n; ++i) {
        char c;
        cin >> c;
        if (c == 'R') ++count[0];
        else if (c == 'G') ++count[1];
        else if (c == 'B') ++count[2];
        else --i;
    }

    array<bool, 3> possible{};
    int nonzero = (count[0] > 0) + (count[1] > 0) + (count[2] > 0);

    if (nonzero == 1) {
        for (int i = 0; i < 3; ++i)
            possible[i] = count[i] > 0;
    } else if (nonzero == 3) {
        possible.fill(true);
    } else {
        int missing = 0;
        while (count[missing] != 0) ++missing;
        possible[missing] = true;

        int first = (missing + 1) % 3;
        int second = (missing + 2) % 3;
        possible[first] = count[second] >= 2;
        possible[second] = count[first] >= 2;
    }

    if (possible[2]) cout << 'B';
    if (possible[1]) cout << 'G';
    if (possible[0]) cout << 'R';

    return 0;
}

