    array<int, 3> count{}; // B, G, R

    for (int i = 0; i < n; ++i) {
        char color;
        cin >> color;

        if (color == 'B') ++count[0];
        else if (color == 'G') ++count[1];
        else if (color == 'R') ++count[2];
        else --i;
    }

    array<bool, 3> possible{};
    int nonzero = 0;

    for (int value : count)
        nonzero += (value > 0);

    if (nonzero == 1) {
        for (int i = 0; i < 3; ++i)
            possible[i] = (count[i] > 0);
    } else if (nonzero == 3) {
        possible.fill(true);
    } else if (nonzero == 2) {
        int missing = -1;
        int first = -1;
        int second = -1;

        for (int i = 0; i < 3; ++i) {
            if (count[i] == 0) {
                missing = i;
            } else if (first == -1) {
                first = i;
            } else {
                second = i;
            }
        }

        possible[missing] = true;
        possible[first] = (count[second] >= 2);
        possible[second] = (count[first] >= 2);
    }

    const char colors[] = {'B', 'G', 'R'};
    for (int i = 0; i < 3; ++i)
        if (possible[i])
            cout << colors[i];

    return 0;
}

