using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> count(3, 0); // R, G, B
    for (int i = 0; i < n; ++i) {
        char c;
        cin >> c;
        if (c == 'R') ++count[0];
        else if (c == 'G') ++count[1];
        else if (c == 'B') ++count[2];
        else --i;
    }

    vector<bool> possible(3, false);
    vector<int> present, absent;

    for (int i = 0; i < 3; ++i) {
        if (count[i] > 0) present.push_back(i);
        else absent.push_back(i);
    }

    if (present.size() == 1) {
        possible[present[0]] = true;
    } else if (present.size() == 3) {
        possible[0] = possible[1] = possible[2] = true;
    } else {
        int x = present[0];
        int y = present[1];
        int z = absent[0];

        if (count[x] == 1 && count[y] == 1) {
            possible[z] = true;
        } else if (count[x] == 1) {
            possible[x] = possible[z] = true;
        } else if (count[y] == 1) {
            possible[y] = possible[z] = true;
        } else {
            possible[0] = possible[1] = possible[2] = true;
        }
    }

    if (possible[2]) cout << 'B';
    if (possible[1]) cout << 'G';
    if (possible[0]) cout << 'R';

    return 0;
}

